# Validation of eikmeans() against Liu, Lu and Zhang (2021), "Concept drift
# detection via equal intensity k-means space partitioning", IEEE Trans.
# Cybernetics 51(6), and its reference code
# (https://github.com/Anjin-Liu/TCYB2019-EIkMeansDriftDetection).
#
# Run from the package root, inside the devcontainer, after
# reference_eikmeans.py (see README.md):
#   Rscript development/validation/eikmeans/run_eikmeans.R [cores]
#
# 1. Equivalence: on the data generated by the reference generators, the
#    partitioning (centroids, amplify-shrink coefficients, training counts),
#    the p-value and the decision of every test window must match the
#    reference code.
# 2. Experiment 2 (Tables III-V): Type-I and Type-II errors on the six 2-D
#    synthetic datasets, training sizes 2000-5000, test windows of 200.
#    Besides the reference data (seed 1), 20 more data seeds drawn in R from
#    the same distributions give the mean and standard deviation.
# 3. Experiment 4 (Tables X-XI): Type-I and Type-II errors on the eight
#    real-world tests (Higgs, MiniBooNE, Arabic digits, Localization, Insects).

devtools::load_all(quiet = TRUE)
args <- commandArgs(trailingOnly = TRUE)
cores <- if (length(args) > 0) as.integer(args[1]) else 6L
data_dir <- file.path("data-real", "eikmeans")
out_dir <- file.path("development", "validation", "results", "eikmeans")
reference_dir <- file.path(out_dir, "reference")

read_data <- function(path) {
  first <- readLines(path, n = 1L)
  as.matrix(utils::read.table(path, sep = if (grepl(",", first)) "," else "", header = FALSE))
}
read_window <- function(folder, kind, t) {
  for (name in c(sprintf("data_%s_%d.csv", kind, t), sprintf("data_%s_%d.csv", toupper(kind), t))) {
    path <- file.path(folder, name)
    if (file.exists(path)) return(read_data(path))
  }
  stop("missing window ", file.path(folder, kind), " ", t)
}

exp2 <- c("2d-U-mean", "2d-1G-mean", "2d-1G-var", "2d-1G-cov", "2d-2G-mean", "2d-4G-mean")
settings <- rbind(
  data.frame(setting = exp2, folder = file.path(data_dir, "exp2", exp2), k = 40, experiment = 2),
  data.frame(setting = c("Higgs-Back", "Back-Higgs", "Sign-Back", "Back-Sign", "Arabic-A-B", "Arabic-B-A",
                         "Localization", "Insect"),
             folder = file.path(data_dir, "exp3", c("1_Higgs/back_higg", "1_Higgs/higg_back",
                                                    "2_MiniBooNeParticle/singal_backgr",
                                                    "2_MiniBooNeParticle/backgr_singal", "3_Arabic_Digit/mix1_mix2",
                                                    "3_Arabic_Digit/mix2_mix1", "4_Localization/mix1",
                                                    "5_Insects/mix1")),
             k = c(40, 40, 40, 40, 40, 40, 60, 40), experiment = 4)
)

# 1 and the seed-1 part of 2 and 3 ------------------------------------------------------
run_setting <- function(i) {
  s <- settings[i, ]
  train <- read_data(file.path(s$folder, "data_train.csv"))
  w0 <- lapply(0:249, function(t) read_window(s$folder, "w0", t))
  w1 <- lapply(0:249, function(t) read_window(s$folder, "w1", t))
  sizes <- if (s$experiment == 2) c(2000, 3000, 4000, 5000) else nrow(train)
  lapply(sizes, function(n_train) {
    started <- Sys.time()
    model <- eikmeans(train[seq_len(n_train), , drop = FALSE], n_test = nrow(w0[[1]]), k = s$k)
    seconds <- as.numeric(difftime(Sys.time(), started, units = "secs"))
    test_all <- function(windows, kind) {
      outcome <- do.call(rbind, lapply(windows, function(w) as.data.frame(eikmeans_test(model, w))))
      data.frame(window = kind, t = 0:249, outcome)
    }
    tests <- rbind(test_all(w0, "w0"), test_all(w1, "w1"))
    list(tests = data.frame(setting = s$setting, experiment = s$experiment, n_train = n_train,
                            bins = nrow(model$centers), seconds = seconds, tests),
         model = model, key = sprintf("%s_n%d", s$setting, n_train))
  })
}
runs <- unlist(parallel::mclapply(seq_len(nrow(settings)), run_setting, mc.cores = cores, mc.preschedule = FALSE),
               recursive = FALSE)
results <- do.call(rbind, lapply(runs, `[[`, "tests"))
models <- stats::setNames(lapply(runs, `[[`, "model"), vapply(runs, `[[`, character(1), "key"))

# 1. Equivalence with the reference
decisions <- utils::read.csv(file.path(reference_dir, "decisions.csv"))
merged <- merge(results[c("setting", "n_train", "window", "t", "p_value", "drift")], decisions,
                by = c("setting", "n_train", "window", "t"), suffixes = c("_r", "_reference"))
merged$drift_reference <- merged$drift_reference == 1
equivalence <- do.call(rbind, lapply(split(merged, list(merged$setting, merged$n_train), drop = TRUE), function(part) {
  key <- sprintf("%s_n%d", part$setting[1], part$n_train[1])
  model <- models[[key]]
  centers <- read_data(file.path(reference_dir, paste0(key, "_centers.csv")))
  amplify <- read_data(file.path(reference_dir, paste0(key, "_amplify.csv")))[, 1]
  counts <- read_data(file.path(reference_dir, paste0(key, "_counts.csv")))[, 1]
  same_shape <- identical(dim(unname(centers)), dim(model$centers))
  data.frame(setting = part$setting[1], n_train = part$n_train[1], bins = nrow(model$centers),
             bins_reference = nrow(centers),
             max_center_difference = if (same_shape) max(abs(unname(centers) - model$centers)) else NA,
             max_amplify_difference = if (same_shape) max(abs(amplify - model$amplify)) else NA,
             counts_equal = identical(as.numeric(counts), as.numeric(model$counts[seq_along(counts)])),
             windows = nrow(part), max_p_difference = max(abs(part$p_value_r - part$p_value_reference)),
             decisions_equal = sum(part$drift_r == part$drift_reference))
}))
equivalence <- equivalence[order(match(equivalence$setting, settings$setting), equivalence$n_train), ]
utils::write.csv(equivalence, file.path(out_dir, "equivalence.csv"), row.names = FALSE)
cat("1. eikmeans() against the reference code\n")
print(format(equivalence, digits = 3), row.names = FALSE)

errors <- function(part) {
  data.frame(type_I = 100 * mean(part$drift[part$window == "w0"]),
             type_II = 100 - 100 * mean(part$drift[part$window == "w1"]))
}
seed1 <- do.call(rbind, lapply(split(results, list(results$setting, results$n_train), drop = TRUE), function(part) {
  cbind(setting = part$setting[1], experiment = part$experiment[1], n_train = part$n_train[1], bins = part$bins[1],
        errors(part))
}))
seed1 <- seed1[order(seed1$experiment, match(seed1$setting, settings$setting), seed1$n_train), ]
utils::write.csv(seed1, file.path(out_dir, "errors_reference_data.csv"), row.names = FALSE)
cat("\n2-3. Type-I and Type-II errors (%) on the data of the reference generators\n")
print(format(seed1, digits = 3), row.names = FALSE)

# 2. More data seeds for Experiment 2 -------------------------------------------------------
gaussian <- function(n, mean, cov = diag(2)) {
  sweep(matrix(stats::rnorm(2 * n), n) %*% chol(cov), 2, mean, "+")
}
generators <- list(
  `2d-U-mean` = function(n, drift) matrix(stats::runif(2 * n), n) + if (drift) 0.06 else 0,
  `2d-1G-mean` = function(n, drift) gaussian(n, c(if (drift) 0.3 else 0, 0)),
  `2d-1G-var` = function(n, drift) gaussian(n, c(0, 0), diag(2) * if (drift) 1.2 else 1),
  `2d-1G-cov` = function(n, drift) gaussian(n, c(0, 0), if (drift) matrix(c(1, 0.2, 0.2, 1), 2) else diag(2)),
  `2d-2G-mean` = function(n, drift) rbind(gaussian(n / 2, c(0, 0)), gaussian(n / 2, c(5 + if (drift) 0.4 else 0, 0))),
  `2d-4G-mean` = function(n, drift) rbind(gaussian(n / 4, c(0, 0)), gaussian(n / 4, c(5, 0)), gaussian(n / 4, c(0, 5)),
                                          gaussian(n / 4, c(5 - if (drift) 0.8 else 0, 5)))
)
seeds <- 2:21
run_seed <- function(job) {
  set.seed(job$seed)
  generate <- generators[[job$setting]]
  # Shuffled as in the reference generator: the mixtures are drawn component by
  # component and the partition is built on the first 2000 points.
  train <- generate(5000, FALSE)
  train <- train[sample.int(nrow(train)), , drop = FALSE]
  w0 <- lapply(1:250, function(t) generate(200, FALSE))
  w1 <- lapply(1:250, function(t) generate(200, TRUE))
  # The partition is built on the first 2000 points for every N, so it is built
  # once and the bins are recounted with the first N points (as fill_lambda).
  base <- eikmeans(train[1:2000, ], n_test = 200, k = 40)
  do.call(rbind, lapply(c(2000, 3000, 4000, 5000), function(n_train) {
    model <- base
    model$counts <- tabulate(heimdall:::.eik_assign(base$centers, base$amplify, train[seq_len(n_train), ]),
                             nbins = nrow(base$centers))
    data.frame(setting = job$setting, seed = job$seed, n_train = n_train, bins = nrow(model$centers),
               type_I = 100 * mean(vapply(w0, function(w) eikmeans_test(model, w)$drift, logical(1))),
               type_II = 100 - 100 * mean(vapply(w1, function(w) eikmeans_test(model, w)$drift, logical(1))))
  }))
}
jobs <- expand.grid(setting = exp2, seed = seeds, stringsAsFactors = FALSE)
seeded <- do.call(rbind, parallel::mclapply(split(jobs, seq_len(nrow(jobs))), run_seed, mc.cores = cores,
                                            mc.preschedule = FALSE))
utils::write.csv(seeded, file.path(out_dir, "exp2_seeds.csv"), row.names = FALSE)
summary_seeds <- do.call(rbind, lapply(split(seeded, list(seeded$setting, seeded$n_train), drop = TRUE), function(p) {
  data.frame(setting = p$setting[1], n_train = p$n_train[1], type_I = mean(p$type_I), type_I_sd = stats::sd(p$type_I),
             type_II = mean(p$type_II), type_II_sd = stats::sd(p$type_II), bins = mean(p$bins))
}))
summary_seeds <- summary_seeds[order(match(summary_seeds$setting, exp2), summary_seeds$n_train), ]
utils::write.csv(summary_seeds, file.path(out_dir, "exp2_seeds_summary.csv"), row.names = FALSE)
cat("\n2. Experiment 2 over", length(seeds), "data seeds drawn in R: mean and sd (%)\n")
print(format(summary_seeds, digits = 3), row.names = FALSE)
